package com.desktodo.app;

import android.content.res.ColorStateList;
import android.graphics.*;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;

/** Shared native presentation: 8dp spacing, 48dp targets and explicit hierarchy. */
final class AppUi {
 static final int INK=Color.rgb(27,46,39),MUTED=Color.rgb(91,108,99),PAPER=Color.rgb(246,247,242),GREEN=Color.rgb(32,87,65),SOFT=Color.rgb(232,239,232),LINE=Color.rgb(218,226,218),DANGER=Color.rgb(153,53,44);
 static GradientDrawable shape(MainActivity a,int color,int radius,boolean border){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(a.dp(radius));if(border)d.setStroke(a.dp(1),LINE);return d;}
 static android.graphics.drawable.Drawable press(MainActivity a,int color,int radius,boolean border){return new RippleDrawable(ColorStateList.valueOf(0x24325e49),shape(a,color,radius,border),null);}
 static Button button(MainActivity a,String title,boolean primary,Runnable action){Button b=new Button(a);b.setText(title);b.setTextSize(15);b.setAllCaps(false);b.setTypeface(null,Typeface.BOLD);b.setTextColor(primary?Color.WHITE:GREEN);b.setMinWidth(a.dp(48));b.setMinimumWidth(a.dp(48));b.setMinHeight(a.dp(48));b.setMinimumHeight(a.dp(48));b.setPadding(a.dp(12),a.dp(10),a.dp(12),a.dp(10));b.setBackground(press(a,primary?GREEN:SOFT,14,false));b.setOnClickListener(v->action.run());return b;}
 static void attach(MainActivity a,LinearLayout parent,View view){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,a.dp(8),0,0);parent.addView(view,p);}
 static LinearLayout row(MainActivity a,LinearLayout parent,String title,String detail,Runnable action){LinearLayout row=new LinearLayout(a);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(a.dp(4),a.dp(12),a.dp(4),a.dp(12));row.setMinimumHeight(a.dp(64));row.setBackground(press(a,Color.TRANSPARENT,10,false));LinearLayout copy=new LinearLayout(a);copy.setOrientation(1);TextView h=a.text(title,16,INK);h.setTypeface(null,Typeface.BOLD);copy.addView(h);if(!detail.isEmpty())copy.addView(a.text(detail,13,MUTED));row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));TextView arrow=a.text("›",26,MUTED);arrow.setPadding(a.dp(12),0,0,0);arrow.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);row.addView(arrow);row.setFocusable(true);row.setContentDescription(title+"，"+detail);row.setOnClickListener(v->action.run());parent.addView(row);return row;}
 static LinearLayout navigation(MainActivity a){LinearLayout bar=new LinearLayout(a);bar.setPadding(a.dp(8),a.dp(4),a.dp(8),a.dp(4));bar.setBackgroundColor(Color.WHITE);String[] names={"工作台","助手","我的"};for(int i=0;i<names.length;i++){String name=names[i];boolean selected=a.topPage().equals(name);LinearLayout item=new LinearLayout(a);item.setOrientation(1);item.setGravity(Gravity.CENTER);item.setMinimumHeight(a.dp(64));item.setPadding(0,a.dp(5),0,a.dp(5));item.setBackground(press(a,selected?SOFT:Color.WHITE,18,false));item.addView(new NavIcon(a,i,selected?GREEN:MUTED),new LinearLayout.LayoutParams(a.dp(24),a.dp(24)));TextView label=a.text(name,12,selected?GREEN:MUTED);label.setGravity(Gravity.CENTER);label.setTypeface(null,selected?Typeface.BOLD:Typeface.NORMAL);item.addView(label);item.setContentDescription(name);item.setSelected(selected);item.setFocusable(true);item.setOnClickListener(v->a.openPage(name));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(a.dp(4),0,a.dp(4),0);bar.addView(item,p);}return bar;}
 static final class NavIcon extends View {final Paint p=new Paint(3);final int type;NavIcon(MainActivity a,int type,int color){super(a);this.type=type;p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.8f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/24f,getHeight()/24f);if(type==0){c.drawRoundRect(4,3,20,21,3,3,p);for(int y:new int[]{8,12,16}){c.drawLine(8,y,9,y,p);c.drawLine(12,y,16,y,p);}}else if(type==1){Path path=new Path();path.moveTo(12,2);path.lineTo(15,9);path.lineTo(22,12);path.lineTo(15,15);path.lineTo(12,22);path.lineTo(9,15);path.lineTo(2,12);path.lineTo(9,9);path.close();c.drawPath(path,p);}else{c.drawCircle(12,7,4,p);c.drawArc(4,13,20,26,190,160,false,p);}c.restore();}}
 static final class LayoutThumb extends View {final String kind;final boolean selected;final Paint p=new Paint(3);LayoutThumb(MainActivity a,String kind,boolean selected){super(a);this.kind=kind;this.selected=selected;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/160f,getHeight()/96f);p.setColor(Color.WHITE);c.drawRoundRect(1,1,159,95,5,5,p);p.setColor(LINE);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);c.drawRoundRect(1,1,159,95,5,5,p);p.setStyle(Paint.Style.FILL);p.setColor(selected?GREEN:MUTED);c.drawRoundRect(9,9,43,15,2,2,p);p.setColor(SOFT);c.drawRect(9,21,151,24,p);int right=kind.equals("minimal")?151:kind.equals("pomodoro")?88:kind.equals("focus")||kind.equals("agenda")?111:100;for(int y:new int[]{34,48,62}){p.setColor(LINE);c.drawRoundRect(9,y,15,y+6,2,2,p);p.setColor(selected?GREEN:MUTED);c.drawRoundRect(21,y,right,y+4,2,2,p);}if(right<150){p.setColor(SOFT);c.drawRoundRect(right+8,32,151,69,3,3,p);}p.setColor(LINE);c.drawRoundRect(9,80,151,87,2,2,p);c.restore();}}
}
